import CoreImage
import XCTest
@testable import KromoraKit

/// Structural checks shared by every Look in the slide/film family (KRMA-1109). The family is the set
/// of manifest entries generated by `SlideLookGenerator`, so a new Look joins automatically and must be
/// declared in `declarations`. There is no reference to match: nothing here compares against a camera,
/// a reference photo or the research parameter table.
final class FilmLookStructureTests: XCTestCase {
    private typealias RGB = SlideLookGenerator.RGB
    private lazy var p3Context = CIContext(options: [.workingColorSpace: WorkingSpace.current.cgColorSpace])

    // MARK: Declarations

    private enum NeutralAxis {
        /// R = G = B along the whole gray ramp.
        case neutral
        /// Chroma stays zero for every chart patch.
        case monochrome
        /// A deliberate split tone: the ramp stays ordered but may carry a tint.
        case toned
        /// Black and white with a deliberate warm tint: luminance carries the image, so the clipping,
        /// gamut-edge and skin checks use luminance like `.monochrome`.
        case tonedMonochrome
    }

    private struct Declaration {
        var neutralAxis: NeutralAxis
        /// Largest relative chroma change allowed on a skin-hue patch (the skinGuard limit).
        var skinChromaChange: Double
        /// Largest hue rotation, in degrees, allowed on a skin-hue patch.
        var skinHueShift: Double
    }

    private static let declarations: [String: Declaration] = [
        "kromora.starter.clean-slide": .init(neutralAxis: .neutral, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.vivid-slide": .init(neutralAxis: .neutral, skinChromaChange: 0.40, skinHueShift: 6),
        "kromora.starter.soft-slide": .init(neutralAxis: .neutral, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.field-report": .init(neutralAxis: .toned, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.portrait-soft": .init(neutralAxis: .neutral, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.portrait-crisp": .init(neutralAxis: .neutral, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.street-negative": .init(neutralAxis: .toned, skinChromaChange: 0.20, skinHueShift: 6),
        "kromora.starter.amber-print": .init(neutralAxis: .toned, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.true-color": .init(neutralAxis: .neutral, skinChromaChange: 0.15, skinHueShift: 6),
        "kromora.starter.cine-flat": .init(neutralAxis: .neutral, skinChromaChange: 0.40, skinHueShift: 6),
        "kromora.starter.silver-bypass": .init(neutralAxis: .neutral, skinChromaChange: 0.70, skinHueShift: 6),
        "kromora.starter.fine-mono": .init(neutralAxis: .monochrome, skinChromaChange: 0, skinHueShift: 0),
        "kromora.starter.fine-mono-yellow": .init(neutralAxis: .monochrome, skinChromaChange: 0, skinHueShift: 0),
        "kromora.starter.fine-mono-red": .init(neutralAxis: .monochrome, skinChromaChange: 0, skinHueShift: 0),
        "kromora.starter.fine-mono-green": .init(neutralAxis: .monochrome, skinChromaChange: 0, skinHueShift: 0),
        "kromora.starter.plain-mono": .init(neutralAxis: .monochrome, skinChromaChange: 0, skinHueShift: 0),
        "kromora.starter.warm-tone": .init(neutralAxis: .tonedMonochrome, skinChromaChange: 0, skinHueShift: 0),
    ]

    /// Relative-ordering checks between Looks. A row is skipped while either Look is not yet shipped.
    private struct Ordering {
        enum Metric { case chroma, contrast }
        var metric: Metric
        var higher: String
        var lower: String
    }

    private static let orderings: [Ordering] = [
        .init(metric: .chroma, higher: "kromora.starter.vivid-slide", lower: "kromora.starter.clean-slide"),
        .init(metric: .chroma, higher: "kromora.starter.soft-slide", lower: "kromora.starter.clean-slide"),
        .init(metric: .chroma, higher: "kromora.starter.clean-slide", lower: "kromora.starter.field-report"),
        .init(metric: .contrast, higher: "kromora.starter.street-negative", lower: "kromora.starter.clean-slide"),
        .init(metric: .contrast, higher: "kromora.starter.clean-slide", lower: "kromora.starter.portrait-soft"),
        .init(metric: .contrast, higher: "kromora.starter.portrait-crisp", lower: "kromora.starter.portrait-soft"),
        .init(metric: .contrast, higher: "kromora.starter.clean-slide", lower: "kromora.starter.cine-flat"),
        .init(metric: .contrast, higher: "kromora.starter.silver-bypass", lower: "kromora.starter.clean-slide"),
        .init(metric: .chroma, higher: "kromora.starter.cine-flat", lower: "kromora.starter.silver-bypass"),
        .init(metric: .contrast, higher: "kromora.starter.fine-mono", lower: "kromora.starter.plain-mono"),
    ]

    // MARK: Fixtures

    private var starterDirectory: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Sources/KromoraKit/Resources/StarterLooks", isDirectory: true)
    }

    private func family() throws -> [(entry: BundledLookManifest.Entry, look: CubeLUT)] {
        let manifest = try BundledLookLibrary.validate()
        let looks = BundledLookLibrary.load().looks
        return try manifest.looks.filter { $0.source.contains("SlideLookGenerator") }.map { entry in
            (entry, try XCTUnwrap(looks.first { $0.id == entry.id }, "\(entry.id) failed to load"))
        }
    }

    // Chart, all in Display P3.
    private static let rampSteps = 33
    private static let hueCount = 12
    private static let hueLuminances: [Double] = [0.25, 0.5, 0.75]
    private static let skinPatches: [RGB] = [
        RGB(0.45, 0.32, 0.26), RGB(0.62, 0.44, 0.35), RGB(0.75, 0.55, 0.45), RGB(0.87, 0.70, 0.60),
    ]
    /// Saturated P3 primaries and secondaries; the pure ones lie beyond the sRGB gamut.
    private static let gamutEdgePatches: [RGB] = [
        RGB(1, 0, 0), RGB(0, 1, 0), RGB(0, 0, 1), RGB(1, 1, 0), RGB(0, 1, 1), RGB(1, 0, 1),
        RGB(0.92, 0.2, 0.1), RGB(0.1, 0.9, 0.3), RGB(0.15, 0.25, 0.95),
    ]

    private struct Chart {
        var ramp: [RGB] = []
        var hues: [RGB] = []
        var skin: [RGB] = []
        var edge: [RGB] = []
        var all: [RGB] { ramp + hues + skin + edge }
    }

    private func makeChart() -> Chart {
        var chart = Chart()
        for i in 0..<Self.rampSteps { chart.ramp.append(RGB(repeating: Double(i) / Double(Self.rampSteps - 1))) }
        for luminance in Self.hueLuminances {
            for h in 0..<Self.hueCount {
                let hue = Double(h) * 360 / Double(Self.hueCount)
                let unit = SlideLookGenerator.hueVector(hue)
                // A fixed-chroma color of this hue at constant mean level, kept inside 0...1.
                var scale = 0.35
                var c = RGB(repeating: luminance) + unit * scale
                while max(c.x, c.y, c.z) > 1 || min(c.x, c.y, c.z) < 0 {
                    scale *= 0.9
                    c = RGB(repeating: luminance) + unit * scale
                }
                chart.hues.append(c)
            }
        }
        chart.skin = Self.skinPatches
        chart.edge = Self.gamutEdgePatches
        return chart
    }

    /// Renders `colors` through `look` in a Display P3 context to float output (no 8-bit clamping).
    private func render(_ colors: [RGB], through look: CubeLUT) throws -> [RGB] {
        var pixels = [Float]()
        for c in colors { pixels += [Float(c.x), Float(c.y), Float(c.z), 1] }
        let input = CIImage(
            bitmapData: Data(bytes: pixels, count: pixels.count * 4), bytesPerRow: pixels.count * 4,
            size: CGSize(width: colors.count, height: 1), format: .RGBAf,
            colorSpace: WorkingSpace.current.cgColorSpace)
        let output = try XCTUnwrap(look.apply(to: input))
        var result = [Float](repeating: 0, count: pixels.count)
        result.withUnsafeMutableBytes {
            p3Context.render(output, toBitmap: $0.baseAddress!, rowBytes: pixels.count * 4,
                             bounds: CGRect(x: 0, y: 0, width: colors.count, height: 1),
                             format: .RGBAf, colorSpace: WorkingSpace.current.cgColorSpace)
        }
        return (0..<colors.count).map { RGB(Double(result[$0 * 4]), Double(result[$0 * 4 + 1]), Double(result[$0 * 4 + 2])) }
    }

    private func chroma(_ c: RGB) -> Double { max(c.x, c.y, c.z) - min(c.x, c.y, c.z) }
    private func luma(_ c: RGB) -> Double { 0.2126 * c.x + 0.7152 * c.y + 0.0722 * c.z }
    private func hue(_ c: RGB) -> Double {
        SlideLookGenerator.hue(of: c - RGB(repeating: (c.x + c.y + c.z) / 3))
    }

    private func clippedPatchIndices(
        inputs: [RGB], outputs: [RGB], neutralAxis: NeutralAxis
    ) -> [Int] {
        zip(inputs, outputs).enumerated().compactMap { index, pair in
            let (input, output) = pair
            if neutralAxis == .monochrome || neutralAxis == .tonedMonochrome {
                let inputLuma = luma(input)
                guard inputLuma > 0.05 && inputLuma < 0.95 else { return nil }
                let outputLuma = luma(output)
                return outputLuma.isFinite && outputLuma > 0.001 && outputLuma < 0.999 ? nil : index
            }

            let channels = [(input.x, output.x), (input.y, output.y), (input.z, output.z)]
            return channels.contains { inputChannel, outputChannel in
                inputChannel > 0.05 && inputChannel < 0.95
                    && (!outputChannel.isFinite || outputChannel <= 0.001 || outputChannel >= 0.999)
            } ? index : nil
        }
    }

    // MARK: Authoring space and format

    func testEveryFamilyCubeIsStampedDisplayP3At33() throws {
        let members = try family()
        XCTAssertFalse(members.isEmpty)
        let stamp = "# \(CubeLUT.authoringSpaceHeaderKey): displayP3"
        for (entry, look) in members {
            XCTAssertEqual(look.size, 33, entry.id)
            XCTAssertEqual(look.authoringSpace, .displayP3, entry.id)
            XCTAssertTrue(entry.approval.notes.contains("KROMORA_AUTHORING_SPACE: displayP3"), "\(entry.id) notes lack P3 authoring")
            let text = try String(contentsOf: starterDirectory.appendingPathComponent(entry.resource), encoding: .utf8)
            XCTAssertEqual(text.split(separator: "\n").filter { $0 == Substring(stamp) }.count, 1, "\(entry.id) stamp")
        }
    }

    func testAnUnstampedOrSRGBCubeIsNotReportedAsDisplayP3() throws {
        let directory = try Fixtures.makeTempDirectory("FilmLookStamp")
        defer { try? FileManager.default.removeItem(at: directory) }
        let body = Fixtures.identityCubeText(size: 3)
        let plain = try CubeLUT(url: Fixtures.writeCube(body, named: "plain.cube", in: directory), source: .user)
        XCTAssertEqual(plain.authoringSpace, .sRGB)
        let stamped = "# \(CubeLUT.authoringSpaceHeaderKey): sRGB\n" + body
        let srgb = try CubeLUT(url: Fixtures.writeCube(stamped, named: "srgb.cube", in: directory), source: .user)
        XCTAssertEqual(srgb.authoringSpace, .sRGB)
        XCTAssertNotEqual(plain.authoringSpace, WorkingSpace.displayP3)
    }

    func testEveryFamilyMemberIsDeclared() throws {
        for (entry, _) in try family() {
            XCTAssertNotNil(Self.declarations[entry.id], "declare \(entry.id) in FilmLookStructureTests.declarations")
        }
    }

    // MARK: Per-Look rendering checks

    func testPerLookStructureOnTheDisplayP3Chart() throws {
        let chart = makeChart()
        for (entry, look) in try family() {
            guard let declaration = Self.declarations[entry.id] else { continue }
            let id = entry.id
            let ramp = try render(chart.ramp, through: look)

            // Tone curve monotonic (strictly: a plateau means the ramp clipped or collapsed).
            for i in 1..<ramp.count {
                XCTAssertGreaterThan(luma(ramp[i]), luma(ramp[i - 1]), "\(id) tone not monotonic at step \(i)")
            }

            // Neutral axis behaves as declared.
            switch declaration.neutralAxis {
            case .neutral:
                for (i, c) in ramp.enumerated() { XCTAssertLessThan(chroma(c), 2e-3, "\(id) neutral step \(i) tinted") }
            case .monochrome:
                for (i, c) in try render(chart.all, through: look).enumerated() {
                    XCTAssertLessThan(chroma(c), 2e-3, "\(id) patch \(i) not monochrome")
                }
            case .toned, .tonedMonochrome:
                break
            }

            // No clipping: interior channels are not pinned to the range ends. For monochrome
            // Looks, check luminance because distinct color patches intentionally become gray.
            let all = chart.all
            let out = try render(all, through: look)
            for index in clippedPatchIndices(inputs: all, outputs: out, neutralAxis: declaration.neutralAxis) {
                XCTFail("\(id) clipped chart patch \(all[index]) to \(out[index])")
            }
            let edge = try render(chart.edge, through: look)
            if declaration.neutralAxis != .monochrome && declaration.neutralAxis != .tonedMonochrome {
                // Distinct P3 gamut-edge patches must not collapse to one clipped color.
                for i in edge.indices {
                    for j in edge.indices where j > i {
                        XCTAssertGreaterThan(((edge[i] - edge[j]) * (edge[i] - edge[j])).sum().squareRoot(), 0.05, "\(id) edge patches \(i) and \(j) collapsed")
                    }
                }
            }

            // Skin-hue patches stay within the skinGuard limit.
            let skin = try render(chart.skin, through: look)
            for (input, result) in zip(chart.skin, skin) where declaration.neutralAxis != .monochrome && declaration.neutralAxis != .tonedMonochrome {
                let change = abs(chroma(result) / chroma(input) - 1)
                var shift = abs(hue(result) - hue(input)).truncatingRemainder(dividingBy: 360)
                if shift > 180 { shift = 360 - shift }
                XCTAssertLessThanOrEqual(change, declaration.skinChromaChange, "\(id) skin chroma \(input)")
                XCTAssertLessThanOrEqual(shift, declaration.skinHueShift, "\(id) skin hue \(input)")
            }
        }
    }

    func testMonochromeNoClipCheckUsesLuminanceForP3GamutEdges() {
        let inputs = [RGB(1, 0, 0), RGB(0, 1, 0), RGB(0, 0, 1)]
        let safeOutputs = [RGB(repeating: 0.22), RGB(repeating: 0.70), RGB(repeating: 0.08)]
        XCTAssertTrue(clippedPatchIndices(inputs: inputs, outputs: safeOutputs, neutralAxis: .monochrome).isEmpty)

        var clippedOutputs = safeOutputs
        clippedOutputs[1] = RGB(repeating: 1)
        XCTAssertEqual(clippedPatchIndices(inputs: inputs, outputs: clippedOutputs, neutralAxis: .monochrome), [1])
    }

    // MARK: Ordering

    func testRelativeOrderingBetweenLooks() throws {
        let chart = makeChart()
        let members = try Dictionary(uniqueKeysWithValues: family().map { ($0.entry.id, $0.look) })
        func metric(_ m: Ordering.Metric, _ look: CubeLUT) throws -> Double {
            switch m {
            case .chroma:
                let out = try render(chart.hues, through: look)
                return out.map(chroma).reduce(0, +) / Double(out.count)
            case .contrast:
                let out = try render(chart.ramp, through: look)
                return luma(out[out.count * 3 / 4]) - luma(out[out.count / 4])
            }
        }
        for row in Self.orderings {
            guard let high = members[row.higher], let low = members[row.lower] else { continue }
            XCTAssertGreaterThan(try metric(row.metric, high), try metric(row.metric, low),
                                 "\(row.higher) should exceed \(row.lower) in \(row.metric)")
        }
    }

    // MARK: Names

    private static let bannedTrademarks = [
        "fuji", "fujifilm", "fujichrome", "fujicolor", "provia", "velvia", "astia", "classic chrome",
        "classic neg", "pro neg", "nostalgic neg", "reala", "superia", "eterna", "acros", "neopan",
        "nps 160", "fortia", "kodachrome", "kodak", "ektachrome", "portra", "color chrome", "fx blue",
    ]

    private func trademarkMatcher() throws -> NSRegularExpression {
        let alternatives = Self.bannedTrademarks
            .map { NSRegularExpression.escapedPattern(for: $0) }
            .joined(separator: "|")
        return try NSRegularExpression(
            pattern: "\\b(?:\(alternatives))\\b", options: [.caseInsensitive]
        )
    }

    private func trademarkMatch(in text: String, using matcher: NSRegularExpression) -> String? {
        let range = NSRange(text.startIndex..., in: text)
        guard let match = matcher.firstMatch(in: text, range: range),
              let matchedRange = Range(match.range, in: text) else { return nil }
        return String(text[matchedRange])
    }

    private func assertNoTrademark(
        in text: String, label: String, using matcher: NSRegularExpression,
        file: StaticString = #filePath, line: UInt = #line
    ) {
        if let name = trademarkMatch(in: text, using: matcher) {
            XCTFail("\(label) mentions \(name)", file: file, line: line)
        }
    }

    func testTrademarkMatcherRecognizesManufacturerAndFilmStockNames() throws {
        let matcher = try trademarkMatcher()
        for name in ["Fujifilm", "Fujichrome", "NPS 160", "Fortia", "Color Chrome FX Blue", "Kodachrome"] {
            XCTAssertNotNil(trademarkMatch(in: name, using: matcher), "expected a trademark match for \(name)")
        }
        XCTAssertNil(trademarkMatch(in: "across the image", using: matcher))
    }

    func testNoTrademarkedNamesInLookNamesManifestOrInspectorStrings() throws {
        let matcher = try trademarkMatcher()
        let manifest = try BundledLookLibrary.validate()
        let loadedLooks = Dictionary(uniqueKeysWithValues: BundledLookLibrary.load().looks.map { ($0.id, $0) })
        let manifestText = try String(
            contentsOf: starterDirectory.appendingPathComponent("manifest.json"), encoding: .utf8
        )
        assertNoTrademark(in: manifestText, label: "manifest", using: matcher)

        for entry in manifest.looks {
            if let look = loadedLooks[entry.id] {
                for field in [look.name, look.category] {
                    assertNoTrademark(in: field, label: "\(entry.id) Look", using: matcher)
                }
            }
            let cube = try String(contentsOf: starterDirectory.appendingPathComponent(entry.resource), encoding: .utf8)
            assertNoTrademark(in: cube, label: entry.resource, using: matcher)
        }

        let views = starterDirectory.deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("Views")
        for file in ["LookInspectorView.swift", "LookSaveSheet.swift"] {
            let source = try String(contentsOf: views.appendingPathComponent(file), encoding: .utf8)
            assertNoTrademark(in: source, label: file, using: matcher)
        }
    }
}
